CREATE TABLE IF NOT EXISTS campaign_actions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  public_id TEXT NOT NULL UNIQUE,
  starts_on TEXT NOT NULL,
  ends_on TEXT NOT NULL,
  front TEXT NOT NULL DEFAULT 'emocional',
  title TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '',
  channel TEXT NOT NULL DEFAULT '',
  owner TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'propuesta',
  created_by_admin_id INTEGER NULL,
  archived_at TEXT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_campaign_actions_range ON campaign_actions (starts_on, ends_on);


INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0010101010101010101010101010101', '2026-10-01', '2026-10-02', 'venta', 'Balance de preventa y ajuste de pauta', 'Revisar en el Panel las entradas por noche y localidad. Mover la pauta hacia las noches con menos ventas (viernes 30 de octubre, lunes 2 y martes 3 de noviembre).', 'Pauta Meta · Panel', 'Pauta y datos', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0020202020202020202020202020202', '2026-10-02', '2026-10-02', 'emocional', 'Cierre de tramo: «Lo que viene es para recordar»', 'Pieza puente entre la revelación del cartel y el tramo de recuerdo. Anuncia que empieza la etapa de memorias, sin datos nuevos.', 'Reel + historias', 'Audiovisual', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0030303030303030303030303030303', '2026-10-03', '2026-10-05', 'emocional', 'Convocatoria «Cuéntanos tu mejor recuerdo de Finados»', 'Motor «Memorias que vuelven». Pedir recuerdos con foto o relato. Publicar solo los autorizados, con consentimiento y sin datos de menores.', 'Reel + historias + comentarios', 'Community', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0040404040404040404040404040404', '2026-10-04', '2026-10-07', 'shows', 'Recuerdo con música: Kjarkas y William Luna (sábado 31 de octubre)', 'Tono de nostalgia: la música que acompañó a las familias. Cada pieza emocional cierra invitando a esa noche y al enlace de entradas.', 'Reel + pauta WhatsApp', 'Audiovisual + Pauta', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0050505050505050505050505050505', '2026-10-05', '2026-10-11', 'venta', 'Empuje a las noches con menos ventas', 'Viernes 30 de octubre (Grupo Bodega y Pablo Noboa), lunes 2 (Cliver y su Grupo Coralí, Sonido Mazter, K’ramelo Latino) y martes 3 de noviembre (El Loco Abraham). Solo precios y localidades confirmados en Ticketstar.', 'Pauta Meta + redes', 'Pauta', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0060606060606060606060606060606', '2026-10-06', '2026-10-09', 'atractivos', 'La tradición que se vive: colada morada y guaguas de pan', 'Recuerdo de la tradición familiar llevado a lo que se vive en la feria: gastronomía, +500 stands y la elección de Rey Pan y Señorita Colada Morada.', 'Carrusel + historias', 'Diseño + Community', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0070707070707070707070707070707', '2026-10-07', '2026-10-07', 'medios', 'Gira de medios: historias de recuerdo', 'Voceros y emprendedores cuentan su recuerdo de Finados en radio y TV. Coordinar desde Medios → Gira de medios.', 'Radio + TV', 'Comunicación', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0080808080808080808080808080808', '2026-10-08', '2026-10-10', 'shows', 'Guaynaa, Waldokinc y Golpe a Golpe (domingo 1 de noviembre)', 'La generación que vuelve a casa para el feriado. Recuerdo + plan con amigos. Incluir a Las Ñañas en la Plaza de la Luna ese mismo día.', 'Reel + TikTok + pauta', 'Audiovisual + Pauta', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0090909090909090909090909090909', '2026-10-09', '2026-10-11', 'participacion', 'Voceros: video «Mi recuerdo de Finados»', 'Pedir a los voceros un video corto con su recuerdo y la invitación a la feria. Revisar y validar views en Voceros.', 'TikTok + Instagram de voceros', 'Community', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0101010101010101010101010101010', '2026-10-12', '2026-10-15', 'emocional', '«Mi familia es tradición»', 'Motor «Familias que comparten». Foto o recuerdo familiar para selección por jurado. Participar, publicar y pautar requieren consentimientos separados.', 'Reel + historias', 'Community', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0111111111111111111111111111111', '2026-10-13', '2026-10-18', 'atractivos', 'Ruta familiar: qué hacer además de los shows', 'Dinosaurios, show de alta escuela, juegos mecánicos, resbaladera gigante y granja turística. Un atractivo por pieza, con horario y ubicación confirmados.', 'Carrusel + Reels', 'Diseño + Audiovisual', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
