INSERT OR IGNORE INTO campaign_actions (public_id, starts_on, ends_on, front, title, detail, channel, owner, status, created_at, updated_at) VALUES ('a0151515151515151515151515151515', '2026-10-12', '2026-10-25', 'venta', 'Elige tu noche en familia', 'Qué noche y qué localidad conviene a cada plan (familia, amigos, pareja). Solo condiciones confirmadas en Ticketstar.', 'Pauta Meta + web SHOWS', 'Pauta + Comercial', 'propuesta', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
